var pool = db.Open(cfg)              // package-level: initialised first
var jobs = make(chan Job, 1024)      // pre-sized queue

func init() {
    for range runtime.NumCPU() {     // pre-spawned workers
        go worker(pool, jobs)
    }
}

func main() {
    if err := pool.Ping(context.Background()); err != nil {
        log.Fatal(err)               // acquired, validated, then serving
    }
    serve()
}
